fields.InputDefinition:
{
  "goal": "Open the 'Event Registrations' entity grid — type 'Event Registrations' in the LEFT sidebar 'Search entities...' box and click it (or navigate to http://localhost:4200/app/data-explorer/Data?entity=Event%20Registrations). Click a row, then 'Open Full Record'. The form has foreign-key fields (e.g. Member, Event). Next to a foreign-key field's value is a small OPEN/NAVIGATE icon (an up-right arrow / external-link icon). Click that icon on one FK field (e.g. Member) to open the RELATED record. Verify a DIFFERENT record's form opens (the URL changes to a different entity/record, e.g. a Member record). Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "Started on an Event Registration record and used a foreign-key field's open/navigate icon",
    "A DIFFERENT related record opened (URL changed to another entity/record, e.g. a Member)",
    "No error messages or crash pages"
  ]
}
